<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { onMounted, ref, watch } from "vue";
import { useResellerAuth } from "@papilio/auth";
import { item, request, query, type Page, type Customer, type CustomerAccessState, type Reseller } from "@papilio/api";
import {useI18n} from "vue-i18n";
import {useLocalizedFormats} from "../composables/useLocalizedFormats";
const {t}=useI18n();const {number}=useLocalizedFormats();
function faNumber(value:number|null):string{return value===null?"—":number(value);}
import NumField from "@papilio/ui/NumField.vue";
import CustomerAccess from "../components/CustomerAccess.vue";
const auth=useResellerAuth(),rows=ref<Customer[]>([]),selected=ref<Customer|null>(null),profile=ref<Reseller|null>(null);
const page=ref(1),pages=ref(1),total=ref(0),q=ref(""),loading=ref(false),busy=ref(false),error=ref(""),profileError=ref(""),notice=ref("");
const name=ref(""),newName=ref(""),telegramId=ref(""),overrideAccess=ref(false),access=ref<CustomerAccessState|null>(null);
let version=0,selectionVersion=0;
async function load():Promise<void>{const current=++version;loading.value=true;error.value="";try{const result=await request<Page<Customer>>(`/v1/reseller/customers?${query({page:page.value,q:q.value})}`);if(current!==version)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(current===version)error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{if(current===version)loading.value=false;}}
async function loadProfile():Promise<void>{profileError.value="";try{const result=await item<Reseller>("/v1/reseller/profile");profile.value=result;if(!overrideAccess.value)access.value={...result.policy.new_customer_access};}catch(cause){profileError.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
async function select(row:Customer,preserve=false):Promise<void>{if(busy.value)return;const current=++selectionVersion;error.value="";try{const result=await item<Customer>(`/v1/reseller/customers/${row.id}`);if(current!==selectionVersion)return;const same=selected.value?.id===row.id;selected.value=result;if(!preserve||!same)name.value=result.display_name;}catch(cause){if(current===selectionVersion)error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
async function create():Promise<void>{if(busy.value||!profile.value||!auth.can("customers","create"))return;busy.value=true;error.value="";notice.value="";try{const row=await item<Customer>("/v1/reseller/customers","POST",{display_name:newName.value,telegram_id:telegramId.value?Number(telegramId.value):null,access:overrideAccess.value?access.value:null});selected.value=row;name.value=row.display_name;newName.value="";telegramId.value="";createOpen.value=false;notice.value=t("resellerCustomers.created");page.value=1;await load();}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{busy.value=false;}}
async function save():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("customers","update"))return;busy.value=true;error.value="";notice.value="";try{selected.value=await item<Customer>(`/v1/reseller/customers/${row.id}`,"PATCH",{display_name:name.value});notice.value=t("resellerCustomers.nameSaved");await load();}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{busy.value=false;}}
watch(q,()=>{page.value=1;void load();});onMounted(()=>{void load();void loadProfile();});
const createOpen=ref(false);
</script>
<template><div class="page-head"><div><p class="eyebrow">{{t("resellerCustomers.eyebrow")}}</p><h1>{{t("resellerCustomers.title")}}</h1><p class="subtitle">{{t("resellerCustomers.subtitle")}}</p></div><button class="btn secondary" :disabled="loading||busy" @click="load">{{t("resellerCustomers.refresh")}}</button><button v-if="auth.can('customers','create')" class="btn" :disabled="busy" @click="createOpen=true">+ {{t("resellerCustomers.create")}}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p><div :class="{split:!!selected}"><section class="card"><div class="card-pad"><label class="field"><span>{{t("resellerCustomers.search")}}</span><input v-model="q" maxlength="120"/></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("resellerCustomers.customer")}}</th><th>{{t("resellerCustomers.telegram")}}</th><th>{{t("resellerCustomers.state")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{row.display_name}}</td><td>{{faNumber(row.telegram_id)}}</td><td>{{row.is_active?t('resellerCustomers.active'):t('resellerCustomers.inactive')}} / {{row.services_enabled?t('resellerCustomers.enabled'):t('resellerCustomers.paused')}} / {{row.renewals_enabled?t('resellerCustomers.enabled'):t('resellerCustomers.paused')}}</td></tr></tbody></table><p v-if="loading" class="empty">{{t("resellerCustomers.loading")}}</p><p v-else-if="!rows.length&&!error" class="empty">{{t("resellerCustomers.empty")}}</p></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t("resellerCustomers.customer")}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section><div class="stack"><section v-if="selected" class="card card-pad"><h2>{{selected.display_name}}</h2><p>{{t("resellerCustomers.id",{id:faNumber(selected.id),telegram:faNumber(selected.telegram_id)})}}</p><p v-if="selected.service_hold_pending" class="hint-box">{{t("resellerCustomers.pendingHold")}}</p><RouterLink v-if="auth.can('subscriptions')" :to="`/reseller/customers/${selected.id}/subscriptions`" class="btn secondary">{{t("resellerCustomers.purchases")}}</RouterLink><form v-if="auth.can('customers','update')" class="form-grid" @submit.prevent="save"><label class="field"><span>{{t("resellerCustomers.displayName")}}</span><input v-model="name" minlength="1" maxlength="120" required :disabled="busy"/></label><button class="btn" :disabled="busy||!name.trim()">{{t("resellerCustomers.saveName")}}</button></form><button class="btn secondary" :disabled="busy" @click="select(selected,true)">{{t("resellerCustomers.refreshRecord")}}</button></section><CustomerAccess v-if="selected" :key="selected.id" :customer="selected" realm="reseller" :policy-allows="profile?.policy.customer_access_override_enabled" @changed="selected=$event;load()"/><Modal v-if="auth.can('customers','create')" v-model="createOpen"  :title="t('resellerCustomers.createTitle')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="profileError" class="message error">{{profileError}} <button class="btn secondary" @click="loadProfile">{{t("resellerCustomers.retry")}}</button></p><p v-if="profile&&!profile.policy.customer_creation_enabled" class="hint-box">{{t("resellerCustomers.creationPaused")}}</p><form v-if="profile?.policy.customer_creation_enabled" class="form-grid" @submit.prevent="create"><fieldset :disabled="busy" class="form-grid"><label class="field"><span>{{t("resellerCustomers.name")}}</span><input v-model="newName" minlength="1" maxlength="120" required/></label><NumField v-model="telegramId"  :label="t('resellerCustomers.telegramOptional')"/><p class="hint-box">{{t("resellerCustomers.telegramHint")}}</p><label v-if="profile.policy.customer_access_override_enabled" class="check-row"><input v-model="overrideAccess" type="checkbox"/>{{t("resellerCustomers.customizeAccess")}}</label><template v-if="overrideAccess&&access"><label class="check-row"><input v-model="access.is_active" type="checkbox"/>{{t("resellerCustomers.accountEnabled")}}</label><label class="check-row"><input v-model="access.services_enabled" type="checkbox"/>{{t("resellerCustomers.serviceEnabled")}}</label><label class="check-row"><input v-model="access.renewals_enabled" type="checkbox"/>{{t("resellerCustomers.renewalEnabled")}}</label></template><p v-else class="hint-box">{{t("resellerCustomers.defaults",{account:profile.policy.new_customer_access.is_active?t("resellerCustomers.active"):t("resellerCustomers.inactive"),service:profile.policy.new_customer_access.services_enabled?t("resellerCustomers.enabled"):t("resellerCustomers.paused"),renewal:profile.policy.new_customer_access.renewals_enabled?t("resellerCustomers.enabled"):t("resellerCustomers.paused")})}}</p><button class="btn" :disabled="!newName.trim()">{{t("resellerCustomers.create")}}</button></fieldset></form></Modal></div></div></template>
<style scoped>fieldset{border:0;padding:0}</style>
